changeSet.sql:
UPDATE staff_profile
SET role_group_id = NULL
WHERE role_group_id IN (SELECT id FROM role_group WHERE code IN ('Q', 'BX', 'G', 'TCN', 'BL'));

UPDATE staff_profile
SET role_group_id = (SELECT id FROM role_group WHERE code = 'DH')
WHERE role_code = 'DH' AND role_group_id IS NULL AND EXISTS (SELECT 1 FROM role_group WHERE code = 'DH');

UPDATE role_group SET name = 'Điều phối' WHERE code = 'DH' AND builtin = 1;

UPDATE role_group_screen
SET perm_level = 'Y'
WHERE screen_key = 'giao-tan-nha' AND role_group_id IN (SELECT id FROM role_group WHERE code = 'DH');

INSERT INTO role_group_screen (role_group_id, screen_key, perm_level)
SELECT rg.id, 'giao-tan-nha', 'Y'
FROM role_group rg
WHERE rg.code = 'DH'
  AND NOT EXISTS (
    SELECT 1 FROM role_group_screen s WHERE s.role_group_id = rg.id AND s.screen_key = 'giao-tan-nha'
  );

UPDATE staff_profile
SET role_group_id = (SELECT id FROM role_group WHERE code = 'AD')
WHERE role_code = 'AD' AND role_group_id IS NULL AND EXISTS (SELECT 1 FROM role_group WHERE code = 'AD');

UPDATE staff_profile
SET role_group_id = (SELECT id FROM role_group WHERE code = 'KT')
WHERE role_code = 'KT' AND role_group_id IS NULL AND EXISTS (SELECT 1 FROM role_group WHERE code = 'KT');
